DROP FUNCTION IF EXISTS "public"."_postgis_scripts_pgsql_version"();
CREATE OR REPLACE FUNCTION "public"."_postgis_scripts_pgsql_version"()
  RETURNS "pg_catalog"."text"
  LANGUAGE sql IMMUTABLE
  COST 100
SELECT '140'::text AS version
;

