CREATE OR REPLACE FUNCTION "public"."get_proj4_from_srid"(int4)
  RETURNS "pg_catalog"."text" AS $BODY$
	BEGIN
	RETURN proj4text::text FROM public.spatial_ref_sys WHERE srid= $1;
	END;
	$BODY$
  LANGUAGE plpgsql IMMUTABLE STRICT
  COST 100;

